class UbootEnv(GenericFct):
    """Ubootenv command class."""

    def __init__(self, connection, operation, params=None, prompt=None, newline_chars=None, options=None, runner=None):
        """
        Ubootenv command.

        :param connection: moler connection to device, terminal when command is executed.
        :param operation: type of operation - get, set or del
        :param params: list of parameters to get, set or del
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param options: Options of FCT Ubootenv command
        :param runner: Runner to run command
        """
        super(UbootEnv, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.operation = operation
        self.params = params
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'uboot_env'
        if self.options:
            cmd = f'{cmd} {self.options}'
        if self.operation:
            cmd = f'{cmd} {self.operation}'
        if self.params:
            for param in self.params:
                cmd = f'{cmd} {param}'
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_deleted(line)
                self._parse_key_value(line)
                self._parse_added(line)
            except ParsingDone:
                pass
        return super(UbootEnv, self).on_new_line(line, is_full_line)

    # Added 1 variables
    _re_deleted = re.compile(r"^Deleted\s(?P<KEY>.*?)=(?P<VALUE>.*)$")

    def _parse_deleted(self, line):
        if self._regex_helper.search_compiled(UbootEnv._re_deleted, line):
            if "Deleted" not in self.current_ret:
                self.current_ret["Deleted"] = {}
            key = self._regex_helper.group("KEY")
            value = self._regex_helper.group("VALUE")
            self.current_ret["Deleted"][key] = value

            if len(self.current_ret["Deleted"]) == len(self.params):
                self.current_ret["Success"] = True
            else:
                self.current_ret["Success"] = False
            raise ParsingDone

    # baudrate=115200
    _re_key_value = re.compile(r"^(?P<KEY>.*?)=(?P<VALUE>.*)$")

    def _parse_key_value(self, line):
        if self._regex_helper.search_compiled(UbootEnv._re_key_value, line):
            key = self._regex_helper.group("KEY")
            value = self._regex_helper.group("VALUE")
            self.current_ret[key] = value
            raise ParsingDone

    # Added 1 variables
    _re_added = re.compile(r"^Added\s(?P<NUMBER>.*)\s")

    def _parse_added(self, line):
        if self._regex_helper.search_compiled(UbootEnv._re_added, line):
            number = self._regex_helper.group("NUMBER")
            if int(number) == len(self.params):
                self.current_ret["Success"] = True
            else:
                self.current_ret["Success"] = False
            raise ParsingDone


